steps.script:
var units = GameState.state["units"]
var keep = ["U_INFILTRATOR_SQUAD_A", "U_GRETCHIN_C"]
for uid in units:
	if not uid in keep:
		for m in units[uid].get("models", []):
			m["alive"] = false
		continue
	units[uid]["flags"] = {}
var px = 40.0
var i = 0
for m in units["U_INFILTRATOR_SQUAD_A"]["models"]:
	if m.get("alive", true):
		m["position"] = {"x": (8.0 + i * 1.6) * px, "y": 20.0 * px}
		i += 1
var j = 0
for m in units["U_GRETCHIN_C"]["models"]:
	if m.get("alive", true):
		m["position"] = {"x": (8.0 + j * 1.4) * px, "y": 34.0 * px}
		j += 1
TerrainManager.set_meta("smo_saved_terrain", TerrainManager.terrain_features.duplicate(true))
var poly = PackedVector2Array([Vector2(3, 16) * px, Vector2(30, 16) * px, Vector2(30, 24) * px, Vector2(3, 24) * px])
TerrainManager.terrain_features = [{"id": "smo_ruin", "type": "ruins", "polygon": poly, "height_category": "tall", "position": Vector2(16.5, 20.0) * px, "size": Vector2(27, 8) * px, "rotation": 0.0, "can_move_through": {"INFANTRY": true, "VEHICLE": false, "MONSTER": false}}]
TerrainManager.emit_signal("terrain_loaded", TerrainManager.terrain_features)
GameState.state["meta"]["first_turn_player"] = 1
GameState.state["meta"]["battle_round"] = 2
GameState.state["meta"]["active_player"] = 2
GameState.state["players"]["1"]["cp"] = 6
GameState.state["players"]["2"]["cp"] = 0
SettingsService.set_auto_allocate_wounds(true)
return "ok"

var u = GameState.get_unit("U_INFILTRATOR_SQUAD_A")
var n = 0
for m in u["models"]:
	if not m.get("alive", true):
		continue
	if not TerrainManager.is_model_hidden(m, u):
		return "model %s NOT hidden (flags %s)" % [str(m.get("id", "?")), str(u.get("flags", {}))]
	n += 1
return n > 0

var p = PhaseManager.get_current_phase_instance()
if not p.has_pending_stratagem_window():
	return "no window"
var w = p.get_pending_stratagem_window()
var ids = []
for o in w.get("offers", []):
	ids.append(str(o.get("stratagem_id", "")))
return str(w.window_id) == "movement_phase_end" and int(w.player) == 1 and "fire_overwatch_11e" in ids

var p = PhaseManager.get_current_phase_instance()
if not p.has_pending_stratagem_window():
	return "no window"
var w = p.get_pending_stratagem_window()
var ids = []
for o in w.get("offers", []):
	ids.append(str(o.get("stratagem_id", "")))
print("[%s] window %s for P%d offers %s" % ["shadow_masters_after_fire_overwatch_11e", str(w.window_id), int(w.player), str(ids)])
return "%s|%d|%s" % [str(w.window_id), int(w.player), ",".join(PackedStringArray(ids))]

var u = GameState.get_unit("U_INFILTRATOR_SQUAD_A")
var D = load("res://scripts/codex/space_marines/SMDetachmentsA.gd")
var f = u.get("flags", {})
print("[%s] P2 Shooting phase, turn %d: hidden=%s can_go_to_ground=%s flags=%s" % ["shadow_masters_after_fire_overwatch_11e", GameState.get_player_turn_index(), str(D.unit_is_hidden(u)), str(TerrainManager.can_go_to_ground(u)), str(f)])
return "%s|%s|%d" % [str(D.unit_is_hidden(u)), str(TerrainManager.can_go_to_ground(u)), int(f.get("last_ranged_attack_idx", -1))]

var u = GameState.get_unit("U_INFILTRATOR_SQUAD_A")
var n = 0
for m in u["models"]:
	if not m.get("alive", true):
		continue
	if not TerrainManager.is_model_hidden(m, u):
		return "model %s NOT hidden (flags %s)" % [str(m.get("id", "?")), str(u.get("flags", {}))]
	n += 1
return n > 0

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_log_file_path(), FileAccess.READ)
if f == null:
	return -1
var n = 0
var bad = []
while not f.eof_reached():
	var l = f.get_line()
	if l.contains("[ERROR"):
		n += 1
		bad.append(l)
print("[shadow_masters_after_fire_overwatch_11e log] ERROR lines = ", n, " ", bad.slice(0, 3))
return n
